package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

public class CommandLine_GetOptionValueTest {

    /**
     * Test helper subclass that lets us control the return value of getOptionValues(OptionGroup).
     * Uses the protected no-arg constructor of CommandLine.
     */
    static class TestableCommandLine extends CommandLine {
        private final String[] toReturn;

        protected TestableCommandLine(final String[] toReturn) {
            super();
            this.toReturn = toReturn;
        }

        @Override
        public String[] getOptionValues(final OptionGroup optionGroup) {
            return toReturn;
        }
    }

    @Test
    public void returnsNullWhenOptionValuesIsNull_viaReflection() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(null);

        Method m = CommandLine.class.getMethod("getOptionValue", OptionGroup.class);
        m.setAccessible(true);

        // pass null OptionGroup as argument; our override ignores it
        Object res = m.invoke(cmd, new Object[] { null });
        assertNull(res);
    }

    @Test
    public void returnsFirstElementWhenArrayHasElements_viaReflection() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(new String[] { "first", "second" });

        Method m = CommandLine.class.getMethod("getOptionValue", OptionGroup.class);
        m.setAccessible(true);

        String result = (String) m.invoke(cmd, new OptionGroup());
        assertEquals("first", result);
    }

    @Test
    public void returnsNullWhenFirstElementIsNull_viaReflection() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(new String[] { null, "second" });

        Method m = CommandLine.class.getMethod("getOptionValue", OptionGroup.class);
        m.setAccessible(true);

        String result = (String) m.invoke(cmd, new OptionGroup());
        assertNull(result);
    }

    @Test
    public void emptyArrayThrowsArrayIndexOutOfBounds_directCall() {
        TestableCommandLine cmd = new TestableCommandLine(new String[0]);
        OptionGroup g = new OptionGroup();

        // Direct call (no reflection) so we observe the raw ArrayIndexOutOfBoundsException
        assertThrows(ArrayIndexOutOfBoundsException.class, () -> cmd.getOptionValue(g));
    }
}

